+
+class handler(BaseHTTPRequestHandler):
+    def do_POST(self):
+        try:
+            auth = self.headers.get('Authorization', '')
+            if not re.fullmatch(r'Bearer [A-Za-z0-9_.-]{20,16000}', auth):
+                raise RequestError(401, 'GitHub 자동화 인증이 필요합니다.')
